data &lt;- within(data, {
  ADSL &lt;- rADSL
  ADAE &lt;- teal.data::rADAE
})


my_custom_module_ui &lt;- function(id) {
  ns &lt;- NS(id)
  tags$div(
    # dataset selector
    selectInput(
      inputId = ns("dataset"),
      label = "Select dataset",
      choices = NULL
    ),
    # ... existing code ...
  )
}


my_custom_module_srv &lt;- function(id, data) {
  moduleServer(id, function(input, output, session) {

    # ... existing code ...

    updateSelectInput(
      inputId = "dataset",
      choices = names(data())
    )

    observeEvent(
      input$dataset,
      {
        req(input$dataset)
        updateSelectInput(
          inputId = "variable",
          choices = data()[[input$dataset]] |&gt; select(where(is.numeric)) |&gt; names()
        )
      }
    )

    # Update reactive and render function
    result &lt;- reactive({
      req(input$dataset)
      req(input$variable)
      within(
        data(),
        {
          my_plot &lt;- ggplot(input_dataset, aes(x = input_var)) +
            geom_histogram()
          my_plot
        },
        input_dataset = as.name(input$dataset),
        input_var = as.name(input$variable)
      )
    })

    output$plot &lt;- renderPlot({
      result()[["my_plot"]]
    })

  })
}
